// upper reads from any io.Reader, writes to any io.Writer
func upper(dst io.Writer, src io.Reader) error {
	b, err := io.ReadAll(src)
	if err != nil {
		return err
	}
	_, err = dst.Write(bytes.ToUpper(b))
	return err
}

func main() {
	var out bytes.Buffer
	_ = upper(&out, strings.NewReader("hello")) // src: strings.Reader, dst: bytes.Buffer
	fmt.Println(out.String()) // Output: HELLO
}

