package main

import (
	"fmt"
	"io"
	"strings"
)

// CountBytes reads r to completion and returns the byte count.
func CountBytes(r io.Reader) (int, error) {
	buf := make([]byte, 4) // tiny buffer to force multiple reads
	total := 0
	for {
		n, err := r.Read(buf)
		total += n          // process the n bytes BEFORE checking err
		if err == io.EOF {  // normal end of stream
			return total, nil
		}
		if err != nil {     // a real error
			return total, err
		}
	}
}

func main() {
	n, _ := CountBytes(strings.NewReader("hello, gophers"))
	fmt.Println(n) // 14
}

