package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func writeLines(w io.Writer, n int) {
	bw := bufio.NewWriter(w) // in-memory buffer batches small writes
	defer bw.Flush()         // CRITICAL: push remaining bytes before return
	for i := 0; i < n; i++ {
		fmt.Fprintf(bw, "line %d\n", i) // writes go to the buffer
	}
	// On return, deferred Flush() turns ~1000 tiny writes into a few syscalls.
}

func main() {
	writeLines(os.Stdout, 1000)
}

