package solution

import (
	"bufio"
	"io"
)

// CountNonEmpty returns the number of non-empty lines read from r.
func CountNonEmpty(r io.Reader) (int, error) {
	sc := bufio.NewScanner(r) // default split is by lines
	count := 0
	for sc.Scan() {           // advances to the next line; false at EOF/err
		if sc.Text() != "" {  // empty line => skip
			count++
		}
	}
	// Scan() returns false on EOF AND on error; distinguish via Err().
	if err := sc.Err(); err != nil {
		return count, err
	}
	return count, nil
}

