package solution

import "io"

// CopyN copies at most n bytes from src to dst, returning the count copied.
func CopyN(dst io.Writer, src io.Reader, n int64) (int64, error) {
	// LimitReader caps src to n bytes; Copy streams it with a small buffer
	// and correctly handles partial reads and io.EOF.
	written, err := io.Copy(dst, io.LimitReader(src, n))
	// io.Copy treats EOF as success; if we copied fewer than n bytes because
	// the source ended early, that's not an error here.
	return written, err
}

package solution

import "io"

// countingReader wraps an io.Reader and tallies bytes read.
type countingReader struct {
	r io.Reader
	n *int64
}

// Read delegates, then records the n bytes (even when err != nil, per the
// io.Reader contract) before returning.
func (c *countingReader) Read(p []byte) (int, error) {
	n, err := c.r.Read(p)
	*c.n += int64(n) // count bytes BEFORE inspecting err (n may be >0 with io.EOF)
	return n, err
}

// CountingReader returns a Reader that behaves like r and a pointer whose
// value is the running total of bytes read through the wrapper.
func CountingReader(r io.Reader) (io.Reader, *int64) {
	count := new(int64)
	return &countingReader{r: r, n: count}, count
}
